export type Booking = { id: number; lab: string; seats: number; purpose: string };

// Wrong: patch is the whole Booking, so the caller must send every field.
export function applyPatch(b: Booking, patch: Booking): Booking {
  return { ...b, ...patch };
}

import { applyPatch } from '../src/patch.ts';
declare const b: { id: number; lab: string; seats: number; purpose: string };
const r = applyPatch(b, { seats: 30 }); // only one field
export { r };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { applyPatch } from '../src/patch.ts';
const b = { id: 1, lab: 'BE-201', seats: 40, purpose: 'Lab' };
test('applyPatch', () => assert.deepEqual(applyPatch(b, { seats: 30 }), { id: 1, lab: 'BE-201', seats: 30, purpose: 'Lab' }));

