export type Booking = { id: number; lab: string; seats: number; purpose: string };

// Partial<Booking>: every field optional — a PATCH body.
export function applyPatch(b: Booking, patch: Partial<Booking>): Booking {
  return { ...b, ...patch };
}

import { applyPatch } from '../src/patch.ts';
declare const b: { id: number; lab: string; seats: number; purpose: string };
const r = applyPatch(b, { seats: 30 }); // only one field
export { r };

