export type Config = { host: string; port: number };

// Wrong: a plain alias — the fields are still writable.
export type FrozenConfig = Config;

import type { FrozenConfig } from '../src/config.ts';
const cfg: FrozenConfig = { host: 'localhost', port: 5432 };
const port: number = cfg.port; // reading is fine
export { port };

import type { FrozenConfig } from '../src/config.ts';
const cfg: FrozenConfig = { host: 'localhost', port: 5432 };
cfg.port = 5433; // expect TS2540
export { cfg };

